if [ "${TOTAL}" -ne 500 ]; then
  echo "WARNING: Expected 500 events but got ${TOTAL}"
  echo "  Windows: ${WINDOWS_COUNT} (expected 200)"
  echo "  Linux: ${LINUX_COUNT} (expected 150)"
  echo "  Network: ${NETWORK_COUNT} (expected 150)"
  exit 1
fi
